import*as schemas from"har-schema";import Ajv from"ajv";import HARError from"./error";let ajv;export function validate(e,t={},r){ajv=ajv||new Ajv({allErrors:!0,schemas:schemas});let n=ajv.getSchema(e+".json"),o=n(t);return"function"==typeof r?r(o?null:new HARError(n.errors),o):o}export function afterRequest(e,t){return validate("afterRequest",e,t)}export function beforeRequest(e,t){return validate("beforeRequest",e,t)}export function browser(e,t){return validate("browser",e,t)}export function cache(e,t){return validate("cache",e,t)}export function content(e,t){return validate("content",e,t)}export function cookie(e,t){return validate("cookie",e,t)}export function creator(e,t){return validate("creator",e,t)}export function entry(e,t){return validate("entry",e,t)}export function har(e,t){return validate("har",e,t)}export function header(e,t){return validate("header",e,t)}export function log(e,t){return validate("log",e,t)}export function page(e,t){return validate("page",e,t)}export function pageTimings(e,t){return validate("pageTimings",e,t)}export function postData(e,t){return validate("postData",e,t)}export function query(e,t){return validate("query",e,t)}export function request(e,t){return validate("request",e,t)}export function response(e,t){return validate("response",e,t)}export function timings(e,t){return validate("timings",e,t)}